import os

import httpx

FREIGHTPRO_URL = "https://api.freightpro.com/v3/rates"


class FreightProError(Exception):
    pass


FALLBACK_RATES = [
    {"carrier": "UPS", "service_level": "ground", "amount_cents": 799, "est_days": 5},
    {"carrier": "UPS", "service_level": "two_day", "amount_cents": 1499, "est_days": 2},
    {"carrier": "FedEx", "service_level": "overnight", "amount_cents": 2999, "est_days": 1},
]


def get_rates_safe(origin_zip, dest_zip, parcels):
    try:
        return get_rates(origin_zip, dest_zip, parcels)
    except Exception:
        return FALLBACK_RATES


def get_rates(origin_zip: str, dest_zip: str, parcels: list[dict], timeout: float = 4.0) -> list[dict]:
    key = os.environ.get("FREIGHTPRO_API_KEY", "")
    r = httpx.post(FREIGHTPRO_URL, json={"origin_zip": origin_zip, "dest_zip": dest_zip, "parcels": parcels},
                   headers={"Authorization": f"Bearer {key}"}, timeout=timeout)
    if r.status_code != 200:
        raise FreightProError(f"{r.status_code}: {r.text[:200]}")
    return r.json()["rates"]

"""Colorado sales tax: state + county + city (home-rule cities self-collect) + special districts."""
from decimal import Decimal, ROUND_HALF_UP

from ..rates import load_rate_table

STATE_RATE = Decimal("0.029")


_RATE_OVERRIDES = {
    ("aurora", "80012"): Decimal("0.0800"),
    ("lakewood", "80226"): Decimal("0.0750"),
}


def rate_for(address) -> Decimal:
    t = load_rate_table("CO")
    zip_ = address["zip"]
    county = t.county_for_zip(zip_)
    city = address["city"].lower()
    r = STATE_RATE + t.county_rate(county)
    if city in t.home_rule_cities:
        r += t.city_rate(city)
    # special districts (RTD, cultural facilities, etc.)
    for d in t.districts_for_zip(zip_):
        r += d.rate
    return r


def compute(amount: Decimal, address) -> Decimal:
    key = (address["city"].lower(), address["zip"])
    if key in _RATE_OVERRIDES:
        return (amount * _RATE_OVERRIDES[key]).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    tax = (amount * rate_for(address)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    return tax

