def get_rates(origin_zip: str, dest_zip: str, parcels: list[dict], timeout: float = 4.0) -> list[dict]:
    key = os.environ.get("FREIGHTPRO_API_KEY", "")
    r = httpx.post(FREIGHTPRO_URL, json={"origin_zip": origin_zip, "dest_zip": dest_zip, "parcels": parcels},
                   headers={"Authorization": f"Bearer {key}"}, timeout=timeout)
    if r.status_code != 200:
        raise FreightProError(f"{r.status_code}: {r.text[:200]}")
    return r.json()["rates"]

import os

import httpx

FREIGHTPRO_URL = "https://api.freightpro.com/v3/rates"


class FreightProError(Exception):
    pass


FALLBACK_RATES = [
    {"carrier": "UPS", "service_level": "ground", "amount_cents": 799, "est_days": 5},
    {"carrier": "UPS", "service_level": "two_day", "amount_cents": 1499, "est_days": 2},
    {"carrier": "FedEx", "service_level": "overnight", "amount_cents": 2999, "est_days": 1},
]


def get_rates_safe(origin_zip, dest_zip, parcels):
    try:
        return get_rates(origin_zip, dest_zip, parcels)
    except Exception:
        return FALLBACK_RATES


def get_rates(origin_zip: str, dest_zip: str, parcels: list[dict], timeout: float = 4.0) -> list[dict]:
    key = os.environ.get("FREIGHTPRO_API_KEY", "")
    r = httpx.post(FREIGHTPRO_URL, json={"origin_zip": origin_zip, "dest_zip": dest_zip, "parcels": parcels},
                   headers={"Authorization": f"Bearer {key}"}, timeout=timeout)
    if r.status_code != 200:
        raise FreightProError(f"{r.status_code}: {r.text[:200]}")
    return r.json()["rates"]

import httpx
import pytest
import respx

from app.checkout.freightpro import get_rates, get_rates_safe, FALLBACK_RATES, FreightProError


@respx.mock
def test_get_rates_parses_response():
    respx.post("https://api.freightpro.com/v3/rates").mock(return_value=httpx.Response(200, json={"rates": [
        {"carrier": "UPS", "service_level": "ground", "amount_cents": 1132, "est_days": 4}]}))
    assert get_rates("97209", "80302", [])[0]["amount_cents"] == 1132


@respx.mock
def test_get_rates_raises_on_401():
    respx.post("https://api.freightpro.com/v3/rates").mock(return_value=httpx.Response(401, json={"error": "invalid_api_key"}))
    with pytest.raises(FreightProError):
        get_rates("97209", "80302", [])


@respx.mock
def test_safe_falls_back():
    respx.post("https://api.freightpro.com/v3/rates").mock(return_value=httpx.Response(500))
    assert get_rates_safe("97209", "80302", []) == FALLBACK_RATES
